function dexamethasoneValues(row,values,s,st){const r=clinicalResult(row);values[0]=row.name+'\n'+(st.product==='validated:dexGeolab01'?'Geolab elixir0,1mg/mL · registro1542300730015 · contém etanol':'Apresentação não selecionada/validada');values[4]=`${s.dose_reference.coefficient} mg/kg/dose VO ÚNICA, máximo12mg por dose neste protocolo. Mínima=máxima do esquema selecionado. Não é faixa universal nem teto diário de outras indicações.`;values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaDexamethasoneClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nAvaliação farmacêutica do teor real de etanol, volume desta dose e dispositivo: '+(st.dexEthanol==='confirmed'?'confirmada pelo profissional':'não confirmada — conversão não liberada');if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}
values[5]=precise(r.doseMin)+' mg de dexametasona em dose única';values[6]=precise(r.doseMax)+' mg, máximo12mg por dose.'+(r.capApplied?' Teto aplicado.':'');for(const col of [7,8])values[col]=r.stockMin===undefined?r.preparationReason:precise(r.stockMin)+' mL do ELIXIR0,1mg/mL, após avaliação individual de etanol e volume. Não usar injetável, gotas ou comprimidos por equivalência presumida.';values[10]=precise(r.doseMin)+' mg VO em dose única, sem intervalo/repetição automática. Uso no crupe apoiado em diretriz, fora da indicação expressa na bula desta apresentação. '+(r.preparationReason?'NÃO ADMINISTRAR: falta avaliação farmacêutica da formulação alcoólica.':precise(r.stockMin)+' mL de elixir0,1mg/mL. Não repetir se vomitar sem reavaliação.');values[11]=r.preparationReason||'Diluição IV, BIC e gotas/min não se aplicam à via oral. Medir com dispositivo oral adequado; não inferir gotas/mL nem divisibilidade de CP.';return values;}
function meropenemValues(row,values,s,st){const r=clinicalResult(row),coef=s.dose_reference.coefficient;values[0]=row.name+' — dose em MEROPENÉM BASE\n'+(st.product==='validated:meropenemBlau1g'?'Blau1g IV · registro1163701870184':'Apresentação não selecionada/validada');values[4]=`${coef} mg/kg/DOSE IV a cada8h; ${coef*3} mg/kg/DIA. Máximo pediátrico da bula120mg/kg/DIA, não por dose. Mínima=máxima do esquema selecionado.`;values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaMeropenemClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nReconstituição específica Blau: frasco1g +20mL água para injetáveis, concentração declarada APROXIMADAMENTE50mg/mL. Volumes/vazões derivados são aproximados. Usar imediatamente; não misturar outros fármacos. Conferir preparo pela farmácia; não transferir os19,1mL do PCH para este produto.\nConcentração de reconstituição50mg/mL: '+(st.meroReconstitution==='label50'?'selecionada':'não selecionada')+'\nDiluente: '+({sf09:'SF0,9%',sg5:'SG5%'}[st.diluent]||'não selecionado/incompatível')+`\nConcentração FINAL: ${st.finalConcentration||'não selecionada'} mg/mL; tempo: ${st.minutes||'não selecionado'}min.`;if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+' mg/dose';values[6]=precise(r.doseMax)+' mg/dose; projeção de3doses/24h: '+precise(r.dailyTherapeutic)+' mg, limitada a '+precise(r.capDaily)+' mg/24h (120mg/kg/dia).';for(const col of [7,8])values[col]=r.stockMin===undefined?r.preparationReason:'Aproximadamente '+precise(r.stockMin)+' mL do concentrado≈50mg/mL, para diluir. Gotas/CP não aplicáveis.';values[10]=precise(r.doseMin)+' mg IV; referência8/8h, sem repetição automática. Projeção para24h: '+precise(r.dailyTherapeutic)+' mg, não exposição já administrada. Duração total depende da indicação/agente/evolução e deve ser prescrita.';values[11]=r.preparationReason||`Preparo aproximado: retirar ${precise(r.stockMin)}mL a≈50mg/mL; completar com ${precise(r.diluentVolume)}mL de ${st.diluent==='sf09'?'SF0,9%':'SG5%'} até volume FINAL ${precise(r.finalVolume)}mL a${r.finalConcentration}mg/mL. Infundir em${r.minutes}min: BIC ${precise(r.rate)}mL/h. Uso imediato, especialmente com SG5%; não misturar outros fármacos; gotas/min não liberadas sem protocolo/fator de equipo.`;values[10]+=r.preparationReason?' NÃO ADMINISTRAR: preparo ainda não liberado.':` Volume final ${precise(r.finalVolume)}mL em${r.minutes}min.`;return values;}
function vancomycinValues(row,values,s,st){const r=clinicalResult(row),mrsa=s.regime_id==='RGM-MED-003-02';values[0]=row.name+' — dose em VANCOMICINA BASE\n'+(st.product==='validated:vancomycinBlau500'?'Blau500mg BASE ·registro1163700920021 ·não usar massa512,6mg do sal':'Apresentação não selecionada/validada');values[4]=mrsa?'15mg/kg/DOSE IV6/6h =60mg/kg/DIA, ponto inicial selecionado no protocolo MRSA. Máximo empírico usual3600mg/dia: acima, cálculo bloqueado para individualização; não teto universal. AUC não estimada.':'10mg/kg/DOSE IV 6/6h =40mg/kg/DIA neste esquema usual. Mínima=máxima. A bula não define teto pediátrico absoluto universal; individualizar por monitorização, sem inventar teto2g/dia.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaVancomycinClinical.requirementsForScheme(st.scheme)).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nReceita selecionada: '+(st.vancoPreparation==='label45'?'500mg +10mL água para injetáveis: volume aproximadamente10,2mL, concentração aproximadamente49mg/mL; adicionar o conteúdo a100mL de diluente, concentração final DECLARADA aproximadamente4,5mg/mL':'não selecionada')+'\nDiluente: '+({sf09:'SF0,9%',sg5:'SG5%'}[st.diluent]||'não selecionado/incompatível')+'; tempo: '+(st.minutes||'não selecionado')+'min. Valores de volume/vazão aproximados pela concentração declarada, não concentração analítica exata.'+(mrsa?'\nMIC: '+({empiric1:'premissa empírica1mg/L, não exame medido',measuredLE1:'resultado por método apropriado≤1mg/L'}[st.vancoMIC]||'não selecionada'):'');if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+'mg/dose';values[6]=precise(r.doseMax)+'mg/dose; projeção de4doses/24h: '+precise(r.dailyTherapeutic)+'mg/dia.'+(mrsa?' Máximo empírico usual3600mg/dia, com monitorização precoce e individualização; não garantia de AUC.':' Sem teto absoluto universal definido nesta bula.');for(const col of [7,8])values[col]=r.stockMin===undefined?r.preparationReason:'Aproximadamente '+precise(r.finalVolume)+'mL da solução JÁ DILUÍDA, concentração declarada≈4,5mg/mL. Não é volume do concentrado49mg/mL. Gotas/CP não liberados.';values[10]=precise(r.doseMin)+'mg IV; esquema selecionado6/6h, sem repetição automática. Duração individual pelo foco/resposta e prescritor; exposição prévia declarada ausente. '+(r.preparationReason?'NÃO ADMINISTRAR: preparo não liberado.':'Volume aproximado '+precise(r.finalVolume)+'mL em'+r.minutes+'min.');values[11]=r.preparationReason||'Preparar frasco inteiro500mg com10mL água para injetáveis, depois adicionar a100mL de '+(st.diluent==='sf09'?'SF0,9%':'SG5%')+' (100mL é DILUENTE, não volume final). Solução final≈4,5mg/mL. Separar apenas o volume da dose: ≈'+precise(r.finalVolume)+'mL, em'+r.minutes+'min; BIC≈'+precise(r.rate)+'mL/h. Não aumentar dose por número inteiro de frascos. Uso imediato; descartar sobra. Nunca IV direto/IM; gotas/min sem fator e protocolo não liberadas.';return values;}
function potassiumValues(row,values,s,st){const r=clinicalResult(row),icu=s.regime_id==='RGM-MED-030-02',hours=icu?1:3,cap=icu?20:10;values[0]=row.name+'\n'+(st.product==='validated:kclHalex191'?'Isofarma/Halex19,1% ·191mg/mL de KCl =2,562mEq/mL de K+ ·registro1031101600033':'Apresentação não selecionada/validada');values[4]=(icu?'0,4mEq/kg/HORA por1h, máximo20mEq/HORA; ciclo total≤0,4mEq/kg e≤20mEq.':'0,2mEq/kg/HORA por3h, máximo10mEq/HORA; ciclo total≤0,6mEq/kg e≤30mEq.')+' Para K+,1mEq=1mmol. Não é dose em mg/kg nem repetição diária automática.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\nK venoso informado: '+(st.kclPotassium||'não informado')+'mmol/L\n'+Object.entries(AnvisaPotassiumClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nDiluente: '+(st.diluent==='sf09'?'SF0,9% sem potássio adicionado':'não selecionado/incompatível')+'; concentração FINAL: '+(st.finalConcentration||'não selecionada')+'mEq/L; ambiente/acesso: '+({wardPeripheral:'enfermaria, IV periférico',icuCentral:'UTI, IV central'}[st.kclSetting]||'não selecionado')+'.';if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+'mEq de K+ no ciclo de'+hours+'h';values[6]=precise(r.doseMax)+'mEq em'+hours+'h; '+precise(r.hourly)+'mEq/h ='+precise(r.coefficient)+'mEq/kg/h. Máximo'+cap+'mEq/h e'+(cap*hours)+'mEq neste ciclo.'+(r.capApplied?' Teto aplicado.':'');for(const col of [7,8])values[col]=precise(r.stockMin)+'mL do concentrado19,1% (2,562mEq/mL) SOMENTE PARA DILUIR. Nunca administrar diretamente; gotas/CP não liberados.';values[10]=precise(r.doseMin)+'mEq IV durante'+hours+'h a'+precise(r.hourly)+'mEq/h; ciclo único, sem repetição automática. Reavaliar K'+(icu?'1h após início e ':'')+'1h após término e antes de outra reposição.'+(r.preparationReason?' NÃO ADMINISTRAR: preparo não liberado.':' Volume FINAL '+precise(r.finalVolume)+'mL, BIC'+precise(r.rate)+'mL/h.');values[11]=(r.finalVolume===undefined?'Selecionar SF0,9% e concentração final40mEq/L.':`Preparo matemático: retirar ${precise(r.stockMin)}mL do concentrado; completar com ${precise(r.diluentVolume)}mL de SF0,9% SEM potássio prévio até volume FINAL ${precise(r.finalVolume)}mL a40mEq/L. BIC ${precise(r.rate)}mL/h durante${hours}h. Não somar o concentrado ao volume final já cheio. Misturar por≥10inversões, rotular bolsa/bomba/linha, descartar sobra da ampola. Nunca flush nem bolus; gotas/min não liberadas.`)+(r.preparationReason?' '+r.preparationReason:'');return values;}
function ondansetronValues(row,values,s,st){const r=clinicalResult(row);values[0]=row.name+' — dose em ONDANSETRONA BASE\n'+(st.product==='validated:ondaHypo2'?'Hypofarma2mg/mL base ·ampola2mL ·registro1038700580010; não usar2,5mg/mL do sal':'Apresentação não selecionada/validada');values[4]='0,1mg/kg/DOSE IV ÚNICA, máximo4mg por dose. Coeficiente e teto originais preservados. Mínima=máxima do esquema selecionado; não aplicar a vômitos inespecíficos.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaOndansetronClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nFunção hepática: '+({noneMild:'avaliada, sem insuficiência moderada/grave',moderateSevere:'insuficiência moderada/grave: teto8mg/24h somando TODAS as vias'}[st.ondaHepatic]||'não selecionada')+'\nPreparo: '+(st.ondaPreparation==='undiluted2'?'IV direta LENTA, solução2mg/mL sem diluição, CHEO':'não selecionado')+'; tempo: '+(st.minutes||'não selecionado')+'min.';if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+'mg de ondansetrona base, dose única';values[6]=precise(r.doseMax)+'mg; teto4mg por dose.'+(r.capApplied?' Teto aplicado.':'')+(r.hepaticDailyCap?' Insuficiência hepática: também máximo8mg/24h por todas as vias.':'');for(const col of [7,8])values[col]=precise(r.stockMin)+'mL da solução2mg/mL BASE. Sem conversão para gotas/CP.';values[10]=precise(r.doseMin)+'mg IV em dose única para indicação perioperatória selecionada; sem intervalo/repetição automática. Exposição24h após esta dose: '+precise(r.exposure24h)+'mg, conforme ausência declarada de doses anteriores.'+(r.preparationReason?' NÃO ADMINISTRAR: preparo não liberado.':' Administrar '+precise(r.stockMin)+'mL a2mg/mL lentamente durante'+r.minutes+'min.');values[11]=r.preparationReason||'Administração IV direta LENTA de'+precise(r.stockMin)+'mL a2mg/mL durante'+r.minutes+'min (CHEO, máximo4mg/dose). Não bolus rápido. BIC/infusão contínua e gotas/min não se aplicam a este contrato; não inferir diluição. Ampola de uso único, usar imediatamente e descartar sobra; não misturar medicamentos.';return values;}
function ampicillinValues(row,values,s,st){const r=clinicalResult(row),coef=s.dose_reference.coefficient;values[0]=row.name+'\n'+(st.product==='validated:ampCilinon1g'?'Cilinon1g ·registro1163700980067 ·1g em volume final3,4mL, concentração calculada1000/3,4mg/mL':'Apresentação não selecionada/validada');values[4]=coef+'mg/kg/DOSE IV6/6h ='+(coef*4)+'mg/kg/DIA antes do teto. Máximo2000mg/dose; ramo6/6h implica máximo8000mg/dia. Posologia UCSF, não posologia literal da bula Cilinon. Mínima=máxima.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaAmpicillinClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nReconstituição: '+(st.ampReconstitution==='label1g3.4'?'Cilinon1g +3mL água para injetáveis →volume FINAL3,4mL (bula)':'não selecionada')+'; diluente: '+(st.diluent==='sf09'?'SF0,9%':'não selecionado/incompatível')+'; concentração FINAL: '+(st.finalConcentration||'não selecionada')+'mg/mL; tempo: '+(st.minutes||'não selecionado')+'min.';if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+'mg/dose';values[6]=precise(r.doseMax)+'mg/dose; projeção4doses/24h: '+precise(r.dailyTherapeutic)+'mg, teto2000mg/dose e8000mg neste ramo6/6h.'+(r.capApplied?' Teto aplicado.':'');for(const col of [7,8])values[col]=precise(r.stockMin)+'mL da reconstituição1g/3,4mL, para posterior diluição. Gotas/CP não liberados.';values[10]=precise(r.doseMin)+'mg IV; referência6/6h, sem repetição automática. '+(s.regime_id==='RGM-MED-009-01'?'UCSF orienta7dias totais na pneumonia não complicada, individualizar resposta e transição oral; não são7dias obrigatórios IV.':s.regime_id==='RGM-MED-009-02'?'Meningite: duração e associações dependem do agente/culturas e infectologia; não inferir duração de outra indicação.':'Duração total de endocardite e associações dependem do agente/foco e infectologia, sem duração automática.')+(r.preparationReason?' NÃO ADMINISTRAR: preparo não liberado.':' Administrar volume FINAL '+precise(r.finalVolume)+'mL em'+r.minutes+'min.');values[11]=r.preparationReason||`Retirar ${precise(r.stockMin)}mL da reconstituição1g/3,4mL; completar com ${precise(r.diluentVolume)}mL SF0,9% até volume FINAL ${precise(r.finalVolume)}mL a125mg/mL(CHEO). Infundir em${r.minutes}min: BIC ${precise(r.rate)}mL/h. Limite:≤10kg,10mg/kg/min;>10kg,100mg/min. Usar imediatamente; não misturar aminoglicosídeos ou outros fármacos. Não transferir receita CHEO7,4mL para Cilinon. Gotas/min não liberadas.`;return values;}
function dobutamineValues(row,values,s,st){const r=clinicalResult(row);values[0]=row.name+' — dose em DOBUTAMINA BASE\n'+(st.product==='validated:dobHypo125'?'Hypofarma12,5mg/mL BASE ·ampola20mL=250mg ·registro1038700570015; não usar14mg/mL do sal':'Apresentação não selecionada/validada');values[4]='5mcg/kg/MINUTO em infusão IV contínua, dose explicitamente selecionada. Mínima=máxima deste ponto; bula pediátrica cita5–20mcg/kg/min, sem extrapolar40adulto nem titular automaticamente.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaDobutamineClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nDiluente: '+({sf09:'SF0,9%',sg5:'SG5%'}[st.diluent]||'não selecionado/incompatível')+'; concentração FINAL: '+(st.finalConcentration||'não selecionada')+'mcg/mL.';if(!r.ok){for(const col of [5,6,7,8,10,11])values[col]=r.reason;return values;}values[5]=precise(r.doseMin)+'mcg/min de dobutamina base';values[6]=precise(r.doseMax)+'mcg/min ='+precise(r.hourlyMg)+'mg/h; não é dose emmg/kg/min nem teto universal.';for(const col of [7,8])values[col]=r.rate===undefined?'NÃO CALCULADO: selecionar concentração FINAL; nunca infundir concentrado12,5mg/mL.':precise(r.rate)+'mL/h da solução FINAL'+r.finalConcentration+'mcg/mL. Sem gotas/CP; verificar bloqueios de preparo.';values[10]='Infusão IV contínua na dose selecionada5mcg/kg/min ='+precise(r.doseMin)+'mcg/min. Duração e titulação são decisões do intensivista conforme resposta; não inferir24/48h nem volume total administrado.'+(r.preparationReason?' NÃO ADMINISTRAR: preparo não liberado.':' BIC'+precise(r.rate)+'mL/h a'+r.finalConcentration+'mcg/mL.');values[11]=(r.finalVolume===undefined?'Selecionar diluente e concentração final.':`Diluir20mL(250mg) de estoque12,5mg/mL com ${precise(r.diluentVolume)}mL de ${st.diluent==='sf09'?'SF0,9%':'SG5%'} ATÉ volume FINAL ${precise(r.finalVolume)}mL, concentração ${r.finalConcentration}mcg/mL. BIC ${precise(r.rate)}mL/h para a dose selecionada. Não adicionar20mL a uma bolsa intacta do volume final. Não usar bicarbonato/soluções alcalinas ou outros medicamentos; monitorizar extravasamento. Gotas/min e bolus não liberados.`)+(r.preparationReason?' '+r.preparationReason:'');return values;}
function epinephrineValues(row,values,s,st){const r=clinicalResult(row),b=s.regime_id.slice(-2);values[0]=row.name+' — epinefrina\n'+(st.product==='validated:epiHyfren1'?'Hyfren1mg/mL ·ampola1mL ·registro1038700820011':'Apresentação não selecionada/validada');values[4]=b==='03'?'0,5mL/kg/DOSE de1mg/mL, máximo5mL=5mg.':b==='02'?'0,01mg/kg/DOSE IV naPCR, máximo1mg.':'0,01mg/kg/DOSE IM naanafilaxia, máximo0,5mg.';values[12]=s.risks;values[13]=s.attention+'\n'+s.notes+'\n'+Object.entries(AnvisaEpinephrineClinical.requirements).map(([k,v])=>v+': '+(st[k]==='confirmed'?'confirmado':'não confirmado')).join('\n')+'\nPreparo selecionado: '+(st.epiPreparation||'nenhum');if(!r.ok){for(const c of [5,6,7,8,10,11])values[c]=r.reason;return values;}values[5]=precise(r.doseMin)+'mg por dose';values[6]=precise(r.doseMax)+'mg por dose; teto deste ramo '+(b==='01'?'0,5mg':b==='02'?'1mg':'5mg=5mL')+'. Mínima=máxima do esquema selecionado; sem teto diário universal.';for(const c of [7,8])values[c]=r.preparationReason||precise(r.volume)+'mL '+(b==='02'?'da solução FINAL0,1mg/mL paraIV':b==='01'?'do estoque1mg/mL paraIM':'do estoque1mg/mL paraNEBULIZAÇÃO, não injetar')+'; semgotas/CP.';values[10]=(b==='01'?'Anafilaxia: '+precise(r.doseMin)+'mg IM na face anterolateral da coxa; reavaliar e repetir após5min somente se necessário sob protocolo.':b==='02'?'PCR: '+precise(r.doseMin)+'mg IV da solução0,1mg/mL; repetição3–5min depende do algoritmoPALS e registro das doses. Não usar para reanimação ao nascimento.':'Crupe grave: '+precise(r.doseMin)+'mL de1mg/mL porNEBULIZAÇÃO; observar3–4h e reavaliar via aérea, sem intervalo fixo automático.')+' Esta saída representa UMA dose.'+(r.preparationReason?' '+r.preparationReason:'');values[11]=r.preparationReason||(b==='01'?'IM:1mg/mL sem diluição; não aplicar diluiçãoPCR. SemBIC/gotas.':b==='02'?'Preparar1mL de estoque1mg/mL +9mL SF0,9% →10mL FINAIS a0,1mg/mL; retirar '+precise(r.volume)+'mL para a dose. Não confundir1mg/mL com0,1mg/mL. SemBIC/gotas.':'NEBULIZAÇÃO off-label: '+precise(r.volume)+'mL de estoque1mg/mL +'+precise(r.diluentVolume)+'mL SF0,9% →'+precise(r.finalVolume)+'mL finais no nebulizador. Não injetar; semBIC/gotas.');return values;}
